window.PIXEL_CHAPTERS=[{"title":"Un panier sur le Nil","ref":"Exode 2,1-10","intro":"En Égypte, le peuple d’Israël subit l’oppression. Une mère cache son petit garçon, puis le place dans un panier parmi les roseaux du Nil. Sa sœur surveille ce qui se passe. La fille de Pharaon le trouve et prend soin de lui : cet enfant sera appelé Moïse.","mission":"Suis les roseaux, retrouve les trois étapes du sauvetage.","reflection":"Dieu veille sur son peuple même dans des moments dangereux. Le récit décrit aussi le courage d’une famille et la compassion d’une princesse.","mood":"Une vie préservée au bord du fleuve","events":[{"title":"Un panier dans les roseaux","ref":"Exode 2,3","body":"La mère de l’enfant prépare un panier, y couche le petit et le dépose parmi les roseaux au bord du Nil.","notice":"Le panier et les roseaux sont dans le récit. Le parcours de labyrinthe, l'apparence des lieux et les objets à toucher sont imaginés."},{"title":"Une sœur attentive","ref":"Exode 2,4","body":"La sœur de l’enfant se tient à distance pour voir ce qui lui arrivera. Elle ne l’abandonne pas du regard.","notice":"Le texte mentionne la sœur qui observe : son apparence est librement illustrée."},{"title":"La fille du Pharaon","ref":"Exode 2,5-10","body":"La fille du Pharaon découvre l’enfant, le prend en compassion et le fait grandir. Il reçoit le nom de Moïse.","notice":"Le récit parle de la fille du Pharaon. Nos vêtements et notre décor de palais sont imaginés."}],"question":{"ask":"Où le bébé Moïse est-il placé ?","answers":["Dans une corbeille parmi les roseaux.","Au milieu d’un palais vide.","Dans une grotte de montagne."],"correct":0,"explain":"Exode 2,3 situe le panier parmi les roseaux au bord du Nil."},"size":[23,19],"seed":9081},{"title":"La voix dans le buisson","ref":"Exode 3,1–4,17","intro":"Devenu adulte, Moïse fait paître un troupeau près de la montagne d’Horeb. Il remarque un buisson en flammes qui ne se consume pas. Dieu l’appelle et lui demande de conduire le peuple hors d’Égypte. Moïse hésite ; Dieu lui assure son aide et annonce celle d’Aaron.","mission":"Explore la montagne, retrouve le troupeau et le lieu de l’appel.","reflection":"La mission dépasse les forces de Moïse. Le récit insiste sur la présence de Dieu et sur une réponse humble à son appel.","mood":"Un appel qui surprend","events":[{"title":"Le troupeau sur la montagne","ref":"Exode 3,1","body":"Moïse garde les brebis de son beau-père et arrive près de la montagne de Dieu. Il mène une vie de berger.","notice":"Le troupeau est mentionné dans Exode 3,1 ; sa disposition dans le jeu est imaginée."},{"title":"Un buisson qui brûle","ref":"Exode 3,2-6","body":"Moïse aperçoit un buisson brûlant sans être détruit. Il s’approche ; Dieu l’appelle et lui demande de retirer ses sandales.","notice":"Le buisson brûlant est biblique. La lumière et les couleurs sont une évocation artistique, pas une représentation de Dieu."},{"title":"Une mission et une aide","ref":"Exode 3,7-10 ; 4,10-17","body":"Dieu annonce qu’il a vu la souffrance de son peuple. Moïse doit aller vers Pharaon ; Aaron l’aidera à parler.","notice":"L'aide d'Aaron est racontée en Exode 4. Le chemin emprunté dans le jeu est imaginé."}],"question":{"ask":"Que demande Dieu à Moïse près du buisson ?","answers":["De retirer ses sandales.","De planter un jardin.","De construire un navire."],"correct":0,"explain":"Exode 3,5 mentionne le retrait des sandales dans ce lieu saint."},"size":[25,21],"seed":9160},{"title":"Face au Pharaon","ref":"Exode 5–11","intro":"Moïse et Aaron demandent au Pharaon de laisser partir le peuple. Le roi refuse et la souffrance s’aggrave. La Bible raconte des signes et des plaies qui frappent l’Égypte. Le but n’est pas de s’amuser des malheurs : c’est un récit grave sur l’oppression, le jugement et la libération.","mission":"Traverse les cours et découvre les paroles de Moïse, d’Aaron et du roi.","reflection":"Le refus obstiné du Pharaon entraîne des conséquences. Dieu ne reste pas indifférent à l’oppression décrite dans le récit.","mood":"Une demande de liberté","events":[{"title":"Une demande de liberté","ref":"Exode 5,1","body":"Moïse et Aaron demandent au Pharaon de laisser partir les Israélites pour célébrer une fête à Dieu.","notice":"La demande au Pharaon est biblique ; les colonnes du palais et le décor sont artistiques."},{"title":"Le refus du roi","ref":"Exode 5,2-9","body":"Le Pharaon rejette leur demande et alourdit le travail des Israélites. Le peuple traverse une épreuve difficile.","notice":"Le refus et le durcissement du travail sont racontés ; la scène évite de tourner la souffrance en spectacle."},{"title":"Les signes en Égypte","ref":"Exode 7–11","body":"Le livre de l’Exode décrit plusieurs plaies touchant l’Égypte. Elles sont présentées comme des événements sérieux, pas comme des tours de magie.","notice":"Les plaies et leurs conséquences sont des événements graves. Le jeu n'en fait pas un défi amusant."}],"question":{"ask":"Qui accompagne Moïse auprès du roi ?","answers":["Aaron.","Jonas.","David."],"correct":0,"explain":"Aaron parle avec Moïse devant Pharaon, comme le raconte Exode 5."},"size":[29,23],"seed":9239},{"title":"La nuit du départ","ref":"Exode 12,1–13,22","intro":"Une nuit décisive arrive en Égypte. Les familles d’Israël se préparent et partagent le repas de la Pâque selon les instructions reçues. Après des événements graves, le Pharaon les laisse partir. Le peuple quitte l’Égypte avec des pains sans levain. La Bible raconte ensuite comment Dieu le guide.","mission":"Retrouve les étapes de préparation et les premiers pas du voyage.","reflection":"La Pâque est une mémoire de la délivrance d’Israël. Nous l’abordons avec respect, sans transformer les souffrances d’Égypte en spectacle.","mood":"Un départ important","events":[{"title":"Le repas de la Pâque","ref":"Exode 12,1-14","body":"Les familles d’Israël se préparent à un repas particulier, qui deviendra un mémorial de leur délivrance.","notice":"Le repas de la Pâque est présenté comme mémorial dans le récit ; les objets visuels du jeu sont imaginés."},{"title":"Des pains sans levain","ref":"Exode 12,33-39","body":"Le départ a lieu rapidement. Les Israélites emportent une pâte qui n’a pas eu le temps de lever.","notice":"La pâte sans levain est mentionnée en Exode 12. Les objets disposés ici sont imaginés."},{"title":"Un peuple en marche","ref":"Exode 13,17-22","body":"Le peuple commence sa route. L’Exode décrit une colonne de nuée le jour et de feu la nuit pour le guider.","notice":"La nuée et la colonne de feu sont décrites dans le texte. Elles sont représentées de façon symbolique."}],"question":{"ask":"Que rappelle la Pâque dans ce récit ?","answers":["Le couronnement de David.","La délivrance d’Israël.","La naissance de Joseph."],"correct":1,"explain":"Exode 12 présente la Pâque comme un mémorial lié à la sortie d’Égypte."},"size":[33,25],"seed":9318},{"title":"Un passage au milieu de la mer","ref":"Exode 14,1-31","intro":"Le peuple arrive près de la mer tandis que les soldats du Pharaon approchent. Les Israélites ont très peur. Moïse les encourage à faire confiance à Dieu. Le récit raconte que Dieu ouvre un passage au milieu des eaux ; le peuple traverse à pied sec. La poursuite égyptienne s’achève tragiquement.","mission":"Explore les rivages et retrouve les étapes du passage sans changer les événements.","reflection":"Le récit de la mer célèbre la délivrance de Dieu. Le jeu invite à observer et à comprendre, jamais à « commander » le miracle.","mood":"Un passage à découvrir","events":[{"title":"La peur devant la mer","ref":"Exode 14,10-12","body":"Avec la mer devant eux et les Égyptiens derrière eux, les Israélites ont peur et appellent au secours.","notice":"La peur des Israélites est racontée en Exode 14. Le labyrinthe n'illustre pas l'emplacement historique exact."},{"title":"La parole de Moïse","ref":"Exode 14,13-14","body":"Moïse encourage les Israélites à ne pas céder à la peur et à observer la délivrance de Dieu.","notice":"La parole de Moïse est racontée en Exode 14,13–14 ; notre personnage et sa tenue sont imaginés."},{"title":"Le chemin ouvert","ref":"Exode 14,21-29","body":"La Bible raconte que la mer se sépare et qu’Israël passe à pied sec. Ce passage est présenté comme l’œuvre de Dieu.","notice":"Le passage à pied sec est raconté en Exode 14 ; le joueur n'ouvre pas lui-même la mer."}],"question":{"ask":"Comment traverse le peuple ?","answers":["Dans des barques de pêche.","Sur un pont de pierre.","À pied sec."],"correct":2,"explain":"Exode 14,22 parle du passage à pied sec au milieu des eaux."},"size":[37,27],"seed":9397}];
